-- 표시를 만든다

@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface Traced { String value() default ""; }

@Service
public class OrderServiceV3 {
    @Traced
    public void orderItem(String itemId) { orderRepository.save(itemId); }

    public void validate(String itemId) { }
}

@Around("@annotation(study.adv.trace.Traced)")
public Object t(ProceedingJoinPoint jp) throws Throwable {
    log.info("걸림 {}", jp.getSignature().toShortString());
    return jp.proceed();
}

