@GetMapping(value = "/anno/visible", produces = "text/plain")
String visible(String type) throws Exception {
    Class<?> a = Class.forName(type);
    Retention r = a.getAnnotation(Retention.class);
    return "보존 %s%n대상 %s%n".formatted(
        r == null ? "CLASS (기본)" : r.value(),
        Arrays.toString(a.getAnnotation(Target.class).value()));
}

